fn is_sorted(a: &[i32]) -> bool {
    // Scan through each adjacent pair; if any predecessor is greater than its successor,
    // the slice is not sorted in nondecreasing order.
    for i in 1..a.len() {
        if a[i - 1] > a[i] {
            return false;
        }
    }
    true
}

